<div class="dashboard-heading"><div><span class="eyebrow">MARKETPLACE</span><h2>Vendedores</h2><p>Acompanhe aprovações, status e comissão aplicada.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Loja</th><th>Documento</th><th>Status</th><th>Comissão</th><th>Cadastro</th></tr></thead><tbody><?php foreach($sellers as $seller): ?><tr><td><strong><?= e($seller['trade_name']) ?></strong></td><td><?= e($seller['document']) ?></td><td><?php $status=$seller['status']; require dirname(__DIR__,2).'/components/dashboard/status-badge.php'; ?></td><td><?= number_format((float)$seller['commission_rate'],2,',','.') ?>%</td><td><?= date('d/m/Y',strtotime($seller['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$sellers): $emptyTitle='Nenhum vendedor cadastrado'; require dirname(__DIR__,2).'/components/dashboard/empty-state.php'; endif; ?></div></section>
